def annotate_grid(grid, palette):
    if not isinstance(grid, list) or not isinstance(palette, dict):
        raise TypeError("grid and palette have invalid types")
    if any(not isinstance(key, str) or not isinstance(value, str)
           for key, value in palette.items()):
        raise TypeError("palette entries must be strings")

    output = []
    for row_number, row in enumerate(grid, 1):
        if not isinstance(row, list):
            raise TypeError("each row must be a list")
        for column_number, cell in enumerate(row, 1):
            if not isinstance(cell, dict):
                raise TypeError("each cell must be a dictionary")
            if set(cell) != {"value", "fill"}:
                raise ValueError("incorrect cell keys")
            fill = cell["fill"]
            if fill is not None and not isinstance(fill, str):
                raise TypeError("fill must be a string or None")
            annotation = "plain" if fill is None else palette.get(fill, "unmapped")
            output.append({
                "row": row_number,
                "column": column_number,
                "value": cell["value"],
                "annotation": annotation,
            })
    return output
```

