import unittest

from solution import annotate_grid


class AnnotateGridTests(unittest.TestCase):
    def test_annotations_and_row_major_coordinates(self):
        grid = [
            [{"value": 1, "fill": None}, {"value": 2, "fill": "red"}],
            [],
            [{"value": 3, "fill": "unknown"}],
        ]
        palette = {"red": "danger"}
        self.assertEqual(annotate_grid(grid, palette), [
            {"row": 1, "column": 1, "value": 1, "annotation": "plain"},
            {"row": 1, "column": 2, "value": 2, "annotation": "danger"},
            {"row": 3, "column": 1, "value": 3, "annotation": "unmapped"},
        ])

    def test_empty_grid_and_rows(self):
        self.assertEqual(annotate_grid([], {}), [])
        self.assertEqual(annotate_grid([[], []], {}), [])

    def test_values_are_deeply_copied(self):
        nested = {"items": [[1], {"key": [2]}]}
        grid = [[{"value": nested, "fill": None}]]
        result = annotate_grid(grid, {})
        nested["items"][0].append(99)
        nested["items"][1]["key"].append(88)
        self.assertEqual(result[0]["value"], {"items": [[1], {"key": [2]}]})
        self.assertIsNot(result[0]["value"], nested)

    def test_inputs_are_not_mutated(self):
        grid = [[{"value": [1], "fill": "x"}]]
        palette = {"x": "marked"}
        annotate_grid(grid, palette)
        self.assertEqual(grid, [[{"value": [1], "fill": "x"}]])
        self.assertEqual(palette, {"x": "marked"})

    def test_wrong_container_and_field_types(self):
        cases = [
            ((), {}),
            ([], []),
            ([()], {}),
            ([[1]], {}),
            ([[{"value": 1, "fill": 2}]], {}),
            ([], {1: "x"}),
            ([], {"x": 1}),
        ]
        for grid, palette in cases:
            with self.subTest(grid=grid, palette=palette), self.assertRaises(TypeError):
                annotate_grid(grid, palette)

    def test_incorrect_cell_keys(self):
        for cell in ({"value": 1}, {"fill": None}, {"value": 1, "fill": None, "extra": 2}):
            with self.subTest(cell=cell), self.assertRaises(ValueError):
                annotate_grid([[cell]], {})


if __name__ == "__main__":
    unittest.main()

